import { Buffer } from 'node:buffer'
import { readFileSync } from 'node:fs'
import { afterEach, describe, expect, it } from 'vitest'
import { parse, stringify } from 'yaml'
import {
  admitArchitectureWiring,
  assertCiArchitectureGate,
  assertPackageArchitectureGate,
  policyOnlyPath,
} from '../scripts/architecture-wiring.mts'
import { budget, ordinaryPolicy, repository } from './fixtures/architecture/repository.ts'

const fixtures: ReturnType<typeof repository>[] = []
afterEach(() => {
  for (const r of fixtures.splice(0)) r.dispose()
})
const json = (value: unknown) => Buffer.from(JSON.stringify(value))
const yaml = (value: unknown) => Buffer.from(stringify(value))
function packageFixture() {
  return {
    dependencies: { renderer: '1.0' },
    scripts: { verify: 'npm run lint && npm test', build: 'original build' },
  }
}
function admittedPackage() {
  const value = packageFixture()
  return {
    ...value,
    scripts: {
      ...value.scripts,
      verify: 'npm run lint && npm run architecture:check && npm test',
      'architecture:check': 'node scripts/architecture-hotspots.mjs --enforce',
      'architecture:report': 'node scripts/architecture-hotspots.mjs',
    },
  }
}
function workflow() {
  return {
    name: 'CI',
    on: { pull_request: {} },
    jobs: {
      verify: {
        steps: [
          { uses: 'actions/checkout@fixed', with: { 'fetch-depth': 0 } },
          { run: 'npm run verify' },
        ],
      },
      smoke: { steps: [{ run: 'npm run smoke' }] },
    },
  }
}
function admittedWorkflow() {
  const value = workflow()
  return {
    ...value,
    jobs: {
      ...value.jobs,
      verify: {
        ...value.jobs.verify,
        permissions: {
          actions: 'read',
          contents: 'read',
          issues: 'read',
          'pull-requests': 'read',
        },
        steps: [
          value.jobs.verify.steps[0]!,
          { run: 'npm run verify', env: { HVIR_REPO_TOKEN: '${{ github.token }}' } },
        ],
      },
    },
  }
}
describe('architecture verification and bounded proposal wiring', () => {
  it('keeps the real local gate and required CI token, permissions, and merge-ref inputs', () => {
    const manifest: unknown = JSON.parse(readFileSync('package.json', 'utf8'))
    const ci: unknown = parse(readFileSync('.github/workflows/ci.yml', 'utf8'))
    expect(() => assertPackageArchitectureGate(manifest)).not.toThrow()
    expect(() => assertCiArchitectureGate(ci)).not.toThrow()
  })
  it('admits only the required package gate changes', () => {
    expect(() =>
      admitArchitectureWiring(
        'package.json',
        json(packageFixture()),
        json(admittedPackage()),
      ),
    ).not.toThrow()
    for (const after of [
      { ...admittedPackage(), dependencies: { renderer: '2.0' } },
      {
        ...admittedPackage(),
        scripts: { ...admittedPackage().scripts, build: 'unrelated product build' },
      },
      {
        ...admittedPackage(),
        scripts: { ...admittedPackage().scripts, verify: 'npm run architecture:check' },
      },
      {
        ...admittedPackage(),
        scripts: {
          ...admittedPackage().scripts,
          'architecture:check': 'node scripts/architecture-hotspots.mjs',
        },
      },
    ])
      expect(() =>
        admitArchitectureWiring('package.json', json(packageFixture()), json(after)),
      ).toThrow()
  })
  it('admits required CI evidence wiring but rejects unrelated jobs, commands, and authority', () => {
    expect(() =>
      admitArchitectureWiring(
        '.github/workflows/ci.yml',
        yaml(workflow()),
        yaml(admittedWorkflow()),
      ),
    ).not.toThrow()
    for (const mutate of [
      (value: ReturnType<typeof admittedWorkflow>) => {
        value.jobs.smoke.steps[0]!.run = 'skip smoke'
      },
      (value: ReturnType<typeof admittedWorkflow>) => {
        value.jobs.verify.permissions.actions = 'write'
      },
      (value: ReturnType<typeof admittedWorkflow>) => {
        value.jobs.verify.steps.push({ run: 'npm run unrelated' })
      },
      (value: ReturnType<typeof admittedWorkflow>) => {
        value.jobs.verify.steps[0] = {
          uses: 'other/checkout@fixed',
          with: { 'fetch-depth': 0 },
        }
      },
    ]) {
      const after = admittedWorkflow()
      mutate(after)
      expect(() =>
        admitArchitectureWiring(
          '.github/workflows/ci.yml',
          yaml(workflow()),
          yaml(after),
        ),
      ).toThrow()
    }
    const extra = {
      ...admittedWorkflow(),
      jobs: {
        ...admittedWorkflow().jobs,
        unrelated: { steps: [{ run: 'echo unrelated' }] },
      },
    }
    expect(() =>
      admitArchitectureWiring('.github/workflows/ci.yml', yaml(workflow()), yaml(extra)),
    ).toThrow()
  })
  it.each([
    'scripts/architecture-product.mts',
    'scripts/architecture-module-product.mts',
    'test/architecture-unrelated.test.ts',
    'test/architecture-module-product.test.ts',
    'test/fixtures/architecture/product.ts',
    'vitest.config.ts',
  ])('rejects invented policy-only identity %s', (path) => {
    expect(policyOnlyPath(path)).toBe(false)
  })
  it('admits current checker owners and deleted bootstrap tests in a complete policy proposal', async () => {
    const r = repository()
    fixtures.push(r)
    r.source(1400)
    const base = r.commit()
    const policy = ordinaryPolicy()
    policy.budgets.push(budget())
    r.policy(policy)
    for (const path of [
      'scripts/architecture-module-graph.mts',
      'scripts/architecture-module-resolution.mts',
      'scripts/architecture-module-directions.mts',
      'test/architecture-module-graph.test.ts',
      'test/architecture-module-directions.test.ts',
      'test/architecture-command.test.ts',
      'test/architecture-hotspots.test.ts',
    ])
      r.source(1, path)
    const report = await r.check(base)
    expect(report.admission.kind).toBe('policy-proposal')
    expect(report.violations).toEqual([])
  })
  it('preserves the exact bootstrap lint insertion without extending native authority to current graph owners', () => {
    const marker = "      'scripts/run-smoke-scenarios.mts',\n"
    const before = Buffer.from(`export default [\n${marker}]\n`)
    const bootstrap = [
      'scripts/architecture-hotspots.mts',
      'scripts/architecture-policy.mts',
      'scripts/architecture-inventory.mts',
      'scripts/architecture-authorization.mts',
      'scripts/architecture-github.mts',
      'scripts/architecture-wiring.mts',
    ]
      .map((path) => `      '${path}',\n`)
      .join('')
    const after = Buffer.from(before.toString().replace(marker, marker + bootstrap))
    expect(() =>
      admitArchitectureWiring('eslint.config.mjs', before, after),
    ).not.toThrow()
    for (const path of [
      'scripts/architecture-module-graph.mts',
      'scripts/architecture-module-resolution.mts',
      'scripts/architecture-module-directions.mts',
    ]) {
      const widened = Buffer.from(
        after.toString().replace(marker, `${marker}      '${path}',\n`),
      )
      expect(() => admitArchitectureWiring('eslint.config.mjs', before, widened)).toThrow(
        /unrelated verification wiring/,
      )
    }
  })
  it('rejects unrelated package work through complete Git proposal admission', async () => {
    const r = repository()
    fixtures.push(r)
    r.source(1400)
    r.write('package.json', json(packageFixture()).toString())
    const base = r.commit()
    const policy = ordinaryPolicy()
    policy.budgets.push(budget())
    r.policy(policy)
    r.write(
      'package.json',
      json({ ...admittedPackage(), dependencies: { renderer: '2.0' } }).toString(),
    )
    await expect(r.check(base)).rejects.toThrow(/unrelated verification wiring/)
  })
})

import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import { describe, expect, it } from 'vitest'

import {
  assertTerminalRuntimeContract,
  verifyInstalledTerminalWasmEvidence,
  verifyTerminalRuntimeContract,
} from '../scripts/check-terminal-runtime.mts'
import { GHOSTTY_TERMINAL_CAPABILITY_PROFILE } from '../scripts/ghostty-terminal-capability-profile.mts'

class CompatibleParser {
  isSynchronizedOutput(): void {}
  getSynchronizedOutputGeneration(): void {}
  resetSynchronizedOutput(): void {}
}

class CompatibleTerminal {
  requestRender(): void {}
  setRenderPaused(): void {}
  resetCursorBlink(): void {}
  getRenderStats(): void {}
  resolveEventProvenance(): void {}
  hasSelection(): void {}
  getSelection(): void {}
  paste(): void {}
  selectAll(): void {}
  clear(): void {}
  reset(): void {}
  searchRetainedBuffer(): void {}
  cancelRetainedBufferSearch(): void {}
  extractRetainedBufferRange(): void {}
  cancelRetainedBufferExtraction(): void {}
  captureRetainedBufferBoundary(): void {}

  registerLinkProvider(provider: object): void {
    const target = this as unknown as {
      readonly linkDetector: {
        registerProvider(candidate: object, priority?: boolean): void
      }
      requestRender(force?: boolean): void
    }
    target.linkDetector.registerProvider(provider, true)
    target.requestRender(true)
  }
}

describe('terminal runtime capability preflight', () => {
  it('accepts the installed ghostty-web runtime contract', () => {
    const root = process.cwd()

    expect(() =>
      execFileSync(process.execPath, [join(root, 'scripts/check-terminal-runtime.mts')], {
        cwd: root,
      }),
    ).not.toThrow()
  })

  it('reports every missing presentation capability and the recovery command', () => {
    class IncompatibleTerminal {}

    expect(() =>
      assertTerminalRuntimeContract({
        Terminal: IncompatibleTerminal,
        GhosttyTerminal: IncompatibleTerminal,
      }),
    ).toThrow(
      /requestRender, setRenderPaused, resetCursorBlink, getRenderStats, resolveEventProvenance, hasSelection, getSelection, paste, selectAll, clear, reset, searchRetainedBuffer, cancelRetainedBufferSearch, extractRetainedBufferRange, cancelRetainedBufferExtraction, captureRetainedBufferBoundary, getScrollbackByteLimit, isSynchronizedOutput, getSynchronizedOutputGeneration, resetSynchronizedOutput, custom link-provider priority and forced render.*npm ci.*retry the command/,
    )
  })

  it('rejects a runtime that lets built-in links override custom routing', () => {
    class UnprioritizedTerminal extends CompatibleTerminal {
      override registerLinkProvider(): void {}
    }

    expect(() =>
      assertTerminalRuntimeContract({
        Terminal: UnprioritizedTerminal,
        GhosttyTerminal: CompatibleParser,
      }),
    ).toThrow(/custom link-provider priority/)
  })

  it('rejects custom link routing that does not invalidate presentation', () => {
    class UnrenderedTerminal extends CompatibleTerminal {
      override registerLinkProvider(provider: object): void {
        const detector = Reflect.get(this, 'linkDetector') as {
          registerProvider(candidate: object, priority?: boolean): void
        }
        detector.registerProvider(provider, true)
      }
    }

    expect(() =>
      assertTerminalRuntimeContract({
        Terminal: UnrenderedTerminal,
        GhosttyTerminal: CompatibleParser,
      }),
    ).toThrow(/custom link-provider priority and forced render/)
  })

  it('rejects unprioritized custom routing even when presentation is invalidated', () => {
    class UnprioritizedRenderedTerminal extends CompatibleTerminal {
      override registerLinkProvider(provider: object): void {
        const target = this as unknown as {
          readonly linkDetector: {
            registerProvider(candidate: object, priority?: boolean): void
          }
          requestRender(force?: boolean): void
        }
        target.linkDetector.registerProvider(provider)
        target.requestRender(true)
      }
    }

    expect(() =>
      assertTerminalRuntimeContract({
        Terminal: UnprioritizedRenderedTerminal,
        GhosttyTerminal: CompatibleParser,
      }),
    ).toThrow(/custom link-provider priority and forced render/)
  })

  it('reports an install mismatch when ghostty-web cannot be loaded', async () => {
    await expect(
      verifyTerminalRuntimeContract(() =>
        Promise.reject(new Error('module unavailable')),
      ),
    ).rejects.toThrow(/ghostty-web could not be loaded.*npm ci.*retry the command/)
  })

  it('reports an install mismatch when the Terminal export is absent', async () => {
    await expect(
      verifyTerminalRuntimeContract(() => Promise.resolve(undefined)),
    ).rejects.toThrow(
      /ghostty-web does not export the required Terminal and GhosttyTerminal constructors.*npm ci.*retry the command/,
    )
  })

  it('matches the installed WASM size to the reviewed capability evidence', async () => {
    await expect(verifyInstalledTerminalWasmEvidence()).resolves.toBeUndefined()
    await expect(
      verifyInstalledTerminalWasmEvidence(async () =>
        Promise.resolve(GHOSTTY_TERMINAL_CAPABILITY_PROFILE.artifact.wasmBytes - 1),
      ),
    ).rejects.toThrow(
      new RegExp(
        `ghostty-vt\\.wasm is ${GHOSTTY_TERMINAL_CAPABILITY_PROFILE.artifact.wasmBytes - 1} bytes; ` +
          `the reviewed capability profile requires ${GHOSTTY_TERMINAL_CAPABILITY_PROFILE.artifact.wasmBytes}.*npm ci`,
      ),
    )
  })

  it('pins the consumed package URL and npm lock integrity', () => {
    const packageJson = JSON.parse(
      readFileSync(new URL('../package.json', import.meta.url), 'utf8'),
    ) as { dependencies: Record<string, string> }
    const packageLock = JSON.parse(
      readFileSync(new URL('../package-lock.json', import.meta.url), 'utf8'),
    ) as { packages: Record<string, { resolved?: string; integrity?: string }> }
    const profile = GHOSTTY_TERMINAL_CAPABILITY_PROFILE

    expect(packageJson.dependencies['ghostty-web']).toBe(profile.artifact.url)
    expect(packageLock.packages['node_modules/ghostty-web']?.resolved).toBe(
      profile.artifact.url,
    )
    expect(packageLock.packages['node_modules/ghostty-web']?.integrity).toBe(
      profile.artifact.npmIntegrity,
    )
  })

  it('runs the preflight before development and production builds', () => {
    const packageJson = JSON.parse(
      readFileSync(new URL('../package.json', import.meta.url), 'utf8'),
    ) as { scripts: Record<string, string> }

    expect(packageJson.scripts.predev).toBe('node scripts/check-terminal-runtime.mts')
    expect(packageJson.scripts.prebuild).toBe('node scripts/check-terminal-runtime.mts')
  })
})

